  {
    "Name": "FileActions",
    "Key": "DocumentManagement",
    "ResourceKey": "DocumentManagement",
    "Content": "",
    "Script": "FileActions = {
    init: async function (app, container) {
        FileActions.app = app || session.app;
        FileActions.container = container || $(".component[name=FileActions]");

        return FileActions;
    },

    deleteSelected: function (event, grid, onComplete) {
        event.preventDefault();

        var files = grid.select();

        if (!files || !files.length) {
            return;
        }

        var dialog = new ConfirmDialog({
            title: "[resource_displayname[areyousure]]",
            question: FileActions.getDeleteQuestion(files),
            close: "[resource_displayname[close]]",
            confirm: "[resource_displayname[confirm]]"
        });

        dialog.events.confirm = async function () {
            try {
                await FileActions.deleteFiles(files);

                dialog.events.close();

                if (onComplete) {
                    await onComplete();
                    return;
                }

                await grid.refresh();
            } catch (err) {
                error(err);
            }
        };

        dialog.init();
    },

    getDeleteQuestion: function (files) {
        return files.length === 1
            ? "[resource_displayname[youwanttodeletethisfile]]"
            : "[resource_displayname[areyousureyouwanttodelete]] " +
                files.length +
                " [resource_displayname[filesthiscannotbeundone]]";
    },

    deleteFiles: async function (files) {
        for (var i = 0; i < files.length; i++) {
            await api.file.destroy(files[i].Path);
        }
    },

    downloadSelected: function (event, grid) {
        event.preventDefault();

        var files = grid.select();

        if (!files || !files.length) {
            return;
        }

        window.location.href = files.length === 1
            ? FileActions.getSingleDownloadUrl(files[0])
            : FileActions.getMultiDownloadUrl(files);
    },

    getSingleDownloadUrl: function (file) {
        return session.apiRoot + "DMS/" + file.Path + "?download";
    },

    getMultiDownloadUrl: function (files) {
        return session.apiRoot +
            "DMS/?downloadPaths=" +
            files.map(function (file) {
                return file.Path;
            }).join();
    },

    expandVersions: async function (event, app, grid, readOnly) {
        var file = grid.dataItem(event.masterRow);
        var host = $("[name=fileVersionGrid]", event.detailRow);

        if (!file || !host.length) {
            return;
        }

        await loadComponent(
            host,
            "FileVersionGrid",
            async function (component) {
                component = component || window.FileVersionGrid;
                await component.init(app,$(".component[name=FileVersionGrid]", host),file,readOnly);
            }
        );
    },

    moveFilesToFolder: async function (files, destinationFolder) {
        if (!files || !files.length || !destinationFolder || !destinationFolder.Path) {
            return;
        }

        for (var i = 0; i < files.length; i++) {
            if (files[i].FolderId && destinationFolder.Id && files[i].FolderId === destinationFolder.Id) {
                continue;
            }

            await api.post(
                "DMS/" +
                files[i].Path +
                "?moveTo=" +
                destinationFolder.Path +
                "/" +
                files[i].Name
            );
        }

        notification.success("[resource_displayname[filemoved]]");
    },

    openRenameSelected: function (event, grid, onComplete) {
    event.preventDefault();

    var files = grid.select();

    if (!files || !files.length) {
        return;
    }

    FileActions.openRename(files, onComplete);
},

    openRename: function (files, onComplete) {
        var dialog = new Dialog({
            title: "[resource_displayname[rename]]",
            height: "auto",
            width: 720
        });

        dialog.template = FileActions.getRenameDialogTemplate(files);

        dialog.init(function () {
            FileActions.bindRenameDialog(dialog, files, onComplete);
        });
    },

    getRenameDialogTemplate: function (files) {
        return [
            '<div class="rename-files-dialog">',
                '<div class="rename-files-intro">',
                    '<div class="rename-files-title">',
                        files.length,
                        ' ',
                        '[resource_displayname[itemselected]]',
                    '</div>',
                    '<div class="rename-files-help">',
                        '[resource_description[renamefilesdescription]]',
                    '</div>',
                '</div>',

                '<div class="rename-files-list" name="renameFilesList">',
                    FileActions.getRenameRowsTemplate(files),
                '</div>',

                '<div class="rename-files-footer">',
                    '<button type="button" class="btn btn-sm btn-primary" name="renameFiles">',
                        '<span class="k-icon k-i-pencil"></span>',
                        '[resource_displayname[rename]]',
                    '</button>',
                '</div>',
            '</div>'
        ].join("");
    },

    getRenameRowsTemplate: function (files) {
        var rows = [];

        for (var i = 0; i < files.length; i++) {
            rows.push([
                '<div class="rename-file-row" data-index="' + i + '">',
                    '<div class="rename-file-icon">',
                        '<img src="' + DMSFormatting.iconPath(files[i].Name) + '" alt="" onerror="this.src=\'[api[root]]DMS/Content/DMSIcons/default.svg\';" />',
                    '</div>',

                    '<div class="rename-file-content">',
                        '<div class="rename-file-original"></div>',

                        '<div class="input-group input-group-sm">',
                            '<span class="input-group-text">[resource_displayname[name]]</span>',
                            '<input type="text" class="form-control" name="newFileName" autocomplete="off" />',
                        '</div>',
                    '</div>',
                '</div>'
            ].join(""));
        }

        return rows.join("");
    },

    bindRenameDialog: function (dialog, files, onComplete) {
        $(".rename-file-row", dialog.element).each(function () {
            var row = $(this);
            var file = files[parseInt(row.attr("data-index"), 10)];

            $(".rename-file-original", row).text(file.Name);
            $("[name=newFileName]", row).val(file.Name);
        });

        $("[name=renameFiles]", dialog.element)
            .off("click.fileActions")
            .on("click.fileActions", async function (event) {
                event.preventDefault();

                await FileActions.renameFiles(dialog, files, onComplete);
            });
    },

    renameFiles: async function (dialog, files, onComplete) {
        var button = $("[name=renameFiles]", dialog.element);
        var renameItems = FileActions.getRenameItems(dialog, files);

        if (!renameItems.length) {
            dialog.events.close();
            return;
        }

        for (var i = 0; i < renameItems.length; i++) {
            if (!renameItems[i].newName) {
                error("[resource_displayname[enterafilename]]");
                renameItems[i].input.trigger("focus");
                return;
            }
        }

        button.prop("disabled", true).text("[resource_displayname[renaming]]");

        try {
            for (var j = 0; j < renameItems.length; j++) {
                await FileActions.renameFile(renameItems[j].file, renameItems[j].newName);
            }

            notification.success("[resource_displayname[filerenamed]]");
            dialog.events.close();

            if (onComplete) {
                await onComplete();
            }
        } catch (err) {
            button
                .prop("disabled", false)
                .html('<span class="k-icon k-i-pencil"></span>[resource_displayname[rename]]');

            error(err);
        }
    },

    getRenameItems: function (dialog, files) {
        var items = [];

        $(".rename-file-row", dialog.element).each(function () {
            var row = $(this);
            var file = files[parseInt(row.attr("data-index"), 10)];
            var input = $("[name=newFileName]", row);
            var newName = (input.val() || "").trim();

            if (!file || newName === file.Name) {
                return;
            }

            items.push({
                file: file,
                newName: newName,
                input: input
            });
        });

        return items;
    },

    renameFile: async function (file, newName) {
        await api.post(
            "DMS/" +
            file.Path +
            "?moveTo=" +
            FileActions.getRenamedFilePath(file, newName)
        );
    },

    getRenamedFilePath: function (file, newName) {
        var folderPath = FileActions.getFileFolderPath(file);

        return folderPath
            ? folderPath + "/" + newName
            : newName;
    },

    getFileFolderPath: function (file) {
        var path = file.Path || "";
        var lastSlash = path.lastIndexOf("/");

        return lastSlash >= 0
            ? path.substring(0, lastSlash)
            : "";
    },
