    "Script": "FolderActions = {
    init: function (app, container) {
        FolderActions.app = app || session.app;
        FolderActions.container = container || $(".component[name=FolderActions]");
        return FolderActions;
    },

    getTemplate: function (name) {
        return $('[name="' + name + '"]', FolderActions.container).first().html();
    },

    openCreate: function (folder, onComplete) {
        var dialog = new Dialog({
            title: "[resource_displayname[newfolder]]",
            height: "auto",
            width: 500
        });

        dialog.template = FolderActions.getTemplate("newFolderDialog");

        dialog.init(function () {
            FolderActions.bindCreateDialog(dialog, folder, onComplete);
        });
    },

    bindCreateDialog: function (dialog, folder, onComplete) {
        var input = $("[name=folderName]", dialog.element);
        var createAtRoot = $("[name=createAtRoot]", dialog.element);
        var preview = $("[name=folderPathPreview]", dialog.element);

        input.val("");
        preview.text(FolderActions.getNewFolderPreviewPath(folder, ""));

        input
            .off("input.folderActions")
            .on("input.folderActions", function () {
                preview.text(
                    FolderActions.getNewFolderPreviewPath(
                        FolderActions.getCreateTargetFolder(dialog, folder),
                        $(this).val()
                    )
                );
            })
            .off("keydown.folderActions")
            .on("keydown.folderActions", function (event) {
                if (event.key === "Enter") {
                    event.preventDefault();
                    $("[name=createFolder]", dialog.element).trigger("click");
                }
            })
            .trigger("focus");

        createAtRoot
            .off("change.folderActions")
            .on("change.folderActions", function () {
                preview.text(
                    FolderActions.getNewFolderPreviewPath(
                        FolderActions.getCreateTargetFolder(dialog, folder),
                        input.val()
                    )
                );
            });

        $("[name=createFolder]", dialog.element)
            .off("click.folderActions")
            .on("click.folderActions", async function (event) {
                event.preventDefault();
                await FolderActions.createFolder(dialog, folder, onComplete);
            });
    },

    createFolder: async function (dialog, parentFolder, onComplete) {
        var input = $("[name=folderName]", dialog.element);
        var button = $("[name=createFolder]", dialog.element);
        var folderName = (input.val() || "").trim();
        var targetParent = FolderActions.getCreateTargetFolder(dialog, parentFolder);

        if (!folderName) {
            error("[resource_displayname[enterafoldername]]");
            input.trigger("focus");
            return;
        }

        button.prop("disabled", true).text("[resource_displayname[creating]]");

        try {
            var createdFolder = await api.post("DocumentManagement/Folder", {
                Name: folderName,
                AppId: FolderActions.app.Id,
                ParentId: targetParent ? targetParent.Id : null
            });

            notification.success("[resource_displayname[foldercreated]]");
            dialog.events.close();

            if (onComplete) {
                await onComplete(createdFolder);
            }
        } catch (err) {
            button
                .prop("disabled", false)
                .html('<span class="k-icon k-i-plus"></span>[resource_displayname[createfolder]]');

            error(err);
        }
    },

    openMove: function (grid, onComplete) {
        var files = grid.select();

        if (!files.length) {
            return;
        }

        var dialog = new Dialog({
            title: "[resource_displayname[move]]",
            height: "auto",
            width: 500
        });

        dialog.template = FolderActions.getTemplate("moveFilesDialog");

        dialog.init(async function () {
            await FolderActions.bindMoveDialog(dialog, grid, files, onComplete);
        });
    },

    bindMoveDialog: async function (dialog, grid, files, onComplete) {
        var treeElement = $("[name=destinationTree]", dialog.element);
        var dataSource = await DocumentManagement.getDataForFoldersTree(grid.app);
        var currentFolderId = FolderActions.getCurrentMoveFolderId(grid, files);

        FolderActions.collapseTree(dataSource);

        if (currentFolderId) {
            FolderActions.expandTreeToFolder(dataSource, currentFolderId);
        }

        var destinationTree = new DataTreeViewWidget(treeElement, {
            dataSource: dataSource,
            template: FolderActions.folderTreeTemplate(),
            dragAndDrop: false
        });

        destinationTree.onSelect = function (event) {
            var node = destinationTree.kendoObject.dataItem(event.node);

            if (!node || !node.folder) {
                return;
            }

            FolderActions.highlightSelectedPath(destinationTree, event.node);
            $("[name=destinationPath]", dialog.element).val(node.folder.Path);
            $("[name=selectedDestinationLabel]", dialog.element)
                .text(FolderActions.formatFolderPath(node.folder));
        };

        destinationTree.init();

        if (currentFolderId) {
            setTimeout(function () {
                FolderActions.selectDestinationFolder(
                    destinationTree,
                    currentFolderId,
                    dialog
                );
            }, 0);
        }
    },

    moveFiles: async function (dialog, files, onComplete) {
        var destinationPath = $("[name=destinationPath]", dialog.element).val();
        var button = $("[name=move]", dialog.element);

        if (!destinationPath) {
            error("[resource_displayname[selectadestination]]");
            return;
        }

        button.prop("disabled", true).text("[resource_displayname[moving]]");

        try {
            await FileActions.moveFilesToFolder(files, { Path: destinationPath });

            dialog.events.close();

            if (onComplete) {
                await onComplete();
            }
        } catch (err) {
            button.prop("disabled", false).text("[resource_displayname[move]]");
            error(err);
        }
    },

    moveFolder: async function (folder, newParentFolder) {
        if (!folder) {
            return null;
        }

        if (newParentFolder) {
            return await FolderActions.moveFolderToFolder(folder, newParentFolder);
        }

        return await FolderActions.moveFolderToRoot(folder);
    },

    moveFolderToFolder: async function (folder, newParentFolder) {
        var payload = {
            Id: folder.Id,
            AppId: folder.AppId,
            Name: folder.Name,
            ParentId: newParentFolder.Id,
            Path: FolderActions.getMovedFolderPath(folder, newParentFolder),
            DeletedOn: folder.DeletedOn || null
        };

        return await api.put(
            "DocumentManagement/Folder(" + folder.Id + ")",
            payload
        );
    },

    moveFolderToRoot: async function (folder) {
        return await $.ajax({
            url: api.apiRoot + "DocumentManagement/Folder(" + folder.Id + ")",
            type: "PATCH",
            contentType: "application/json",
            data: JSON.stringify({
                ParentId: null
            })
        });
    },

    getMovedFolderPath: function (folder, newParentFolder) {
        var folderName = (folder.Name || "").trim().toLowerCase();

        if (!newParentFolder || !newParentFolder.Path) {
            return folderName;
        }

        return newParentFolder.Path.replace(/\/+$/g, "") + "/" + folderName;
    },

    openManage: function (folder, onComplete) {
        var dialog = new Dialog({
            title: "[resource_displayname[managefolder]]",
            width: 1000
        });

        dialog.template = FolderActions.getTemplate("manageFolderDialog");

        dialog.init(async function () {
            await FolderActions.bindManageDialog(dialog, folder, onComplete);
        });
    },

    bindManageDialog: async function (dialog, folder, onComplete) {
        $("[name=manageFolderTabs]", dialog.element).kendoTabStrip({
            animation: { open: { effects: "fadeIn" } }
        });

        $("[name=manageFolderName]", dialog.element).val(folder.Name);
        $("[name=manageFolderPath]", dialog.element).text(FolderActions.formatFolderPath(folder));

        FolderActions.bindManageButton(dialog, "renameFolder", function () {
            return FolderActions.renameFolder(dialog, folder, onComplete);
        });

        FolderActions.bindManageButton(dialog, "downloadFolder", function () {
            FolderActions.downloadFolder(folder);
        });

        FolderActions.bindManageButton(dialog, "deleteFolder", function () {
            FolderActions.deleteFolder(dialog, folder, onComplete);
        });

        await FolderActions.loadFolderRoles(dialog, folder);
        await FolderActions.loadFolderEvents(dialog, folder);
    },

    bindManageButton: function (dialog, name, handler) {
        dialog.element
            .off("click.folderActions", '[name="' + name + '"]')
            .on("click.folderActions", '[name="' + name + '"]', function (event) {
                event.preventDefault();
                event.stopPropagation();
                handler(event);
            });
    },

    renameFolder: async function (dialog, folder, onComplete) {
        var input = $("[name=manageFolderName]", dialog.element);
        var button = $("[name=renameFolder]", dialog.element);
        var newName = (input.val() || "").trim();

        if (!newName) {
            error("[resource_displayname[enterafoldername]]");
            input.trigger("focus");
            return;
        }

        if (newName === folder.Name) {
            return;
        }

        button.prop("disabled", true).text("[resource_displayname[renaming]]");

        try {
            var payload = $.extend(true, {}, folder);
            payload.Name = newName;

            var updatedFolder = await api.put("DocumentManagement/Folder(" + folder.Id + ")", payload);

            $.extend(true, folder, updatedFolder || payload);

            notification.success("[resource_description[folderrenamedsuccessfully]]");
            dialog.events.close();

            if (onComplete) {
                await onComplete(folder);
            }
        } catch (err) {
            button.prop("disabled", false).text("[resource_displayname[rename]]");
            error(err);
        }
    },

    deleteFolder: function (dialog, folder, onComplete) {
        if (dialog && dialog.events && dialog.events.close) {
            dialog.events.close();
        }

        setTimeout(function () {
            var confirmation = new ConfirmDialog({
                title: "[resource_displayname[DeleteFolderTitle]]: " + FolderActions.formatFolderPath(folder),
                question: "[resource_displayname[deleteconfirmation]]",
                confirm: "[resource_displayname[confirm]]",
                close: "[resource_displayname[cancel]]"
            });

            confirmation.events.confirm = async function (event) {
                try {
                    if (typeof folder.destroy !== "function") {
                        model.prepareItem(folder, await api.getType("DocumentManagement/Folder"));
                    }

                    await folder.destroy(event);

                    notification.success("[resource_description[FolderDeletedSuccesfully]]");
                    confirmation.events.close();

                    if (onComplete) {
                        await onComplete(folder);
                    }
                } catch (err) {
                    console.error("Folder deletion failed:", err);
                    error(err);
                }
            };

            confirmation.init();
        }, 0);
    },

    downloadFolder: function (folder) {
        if (!folder || !folder.Path) {
            error("[resource_displayname[folderpathnotfound]]");
            return;
        }

        window.location.href =
            session.apiRoot +
            "DMS/" +
            folder.Path.split("/").map(encodeURIComponent).join("/");
    },

    loadFolderRoles: function (dialog, folder) {
        return FolderActions.loadFolderComponent(dialog, "folderRolesHost", "FolderRoles", folder);
    },

    loadFolderEvents: function (dialog, folder) {
        return FolderActions.loadFolderComponent(dialog, "folderEventsHost", "FolderEventManager", folder);
    },

    loadFolderComponent: async function (dialog, hostName, componentName, folder) {
        var host = $('[name="' + hostName + '"]', dialog.element);

        await loadComponent(host, componentName, async function (component) {
            component = component || window[componentName];

            if (component && component.init) {
                await component.init(FolderActions.app, host, folder);
            }
        });
    },

    collapseTree: function (items) {
        for (var i = 0; i < items.length; i++) {
            items[i].expanded = false;

            if (items[i].items && items[i].items.length) {
                FolderActions.collapseTree(items[i].items);
            }
        }

        return items;
    },

    folderTreeTemplate: function () {
        return [
            '<span class="document-tree-node">',
                '<img class="document-tree-node-icon" ',
                    'src="[api[root]]DMS/Content/DMSIcons/treefolder.svg" ',
                    'alt="" ',
                '/>',
                '<span class="document-tree-node-text mx-1">#: item.text #</span>',
            '</span>'
        ].join("");
    },

    highlightSelectedPath: function (tree, node) {
        var treeElement = tree.treeElement || tree.element || tree.kendoObject.element;

        $(".document-tree-parent-selected", treeElement).removeClass("document-tree-parent-selected");

        $(node)
            .parents("li.k-treeview-item")
            .children(".k-treeview-top, .k-treeview-mid, .k-treeview-bot, .k-in, .k-treeview-leaf")
            .addClass("document-tree-parent-selected");
    },

    formatFolderPath: function (folder) {
        return window.DMSFormatting
            ? DMSFormatting.folderPath(folder)
            : (folder.Path || folder.Name || "").split("/").filter(Boolean).join(" / ");
    },

    getCurrentMoveFolderId: function (grid, files) {
        if (grid && grid.folder && grid.folder.Id) {
            return grid.folder.Id;
        }

        if (files && files.length && files[0].FolderId) {
            return files[0].FolderId;
        }

        return null;
    },

    expandTreeToFolder: function (items, folderId) {
        for (var i = 0; i < items.length; i++) {
            if (items[i].id == folderId) {
                items[i].expanded = true;
                return true;
            }

            if (
                items[i].items &&
                items[i].items.length &&
                FolderActions.expandTreeToFolder(items[i].items, folderId)
            ) {
                items[i].expanded = true;
                return true;
            }
        }

        return false;
    },

    selectDestinationFolder: function (tree, folderId, dialog) {
        var node = FolderActions.findTreeNodeByFolderId(
            tree.kendoObject,
            folderId
        );

        if (!node || !node.length) {
            return;
        }

        tree.kendoObject.select(node);

        var nodeData = tree.kendoObject.dataItem(node);

        if (nodeData && nodeData.folder) {
            $("[name=destinationPath]", dialog.element).val(nodeData.folder.Path);
            $("[name=selectedDestinationLabel]", dialog.element)
                .text(FolderActions.formatFolderPath(nodeData.folder));
        }

        FolderActions.highlightSelectedPath(tree, node);
    },

    findTreeNodeByFolderId: function (kendoTree, folderId) {
        var dataItem = FolderActions.findTreeDataItemByFolderId(
            kendoTree.dataSource.view(),
            folderId
        );

        if (!dataItem) {
            return null;
        }

        return kendoTree.findByUid(dataItem.uid);
    },

    findTreeDataItemByFolderId: function (items, folderId) {
        for (var i = 0; i < items.length; i++) {
            if (items[i].id == folderId) {
                return items[i];
            }

            var child = FolderActions.findTreeDataItemByFolderId(
                items[i].items || [],
                folderId
            );

            if (child) {
                return child;
            }
        }

        return null;
    },

    getCreateTargetFolder: function (dialog, parentFolder) {
        return $("[name=createAtRoot]", dialog.element).is(":checked")
            ? null
            : parentFolder;
    },

    getNewFolderPreviewPath: function (parentFolder, folderName) {
        var name = (folderName || "").trim();
        var parentPath = parentFolder
            ? FolderActions.formatFolderPath(parentFolder)
            : "";

        if (!name) {
            return parentPath ? parentPath + " / " : "";
        }

        return parentPath ? parentPath + " / " + name : name;
    },
