  {
    "Name": "FolderManagement",
    "Key": "DocumentManagement",
    "ResourceKey": "DocumentManagement",
    "Content": "",
    "Script": "FolderManagement = {
        init: async function (app, container, folder, readOnly, disablePaging = false) {
        app = app || session.app;
        container = container || $(".component[name=FolderManagement]");
        readOnly = readOnly || false;

        if (!folder) {
            return;
        }

        api.addToMetaCache([{
            Name: "DocumentManagement",
            Types: [
                [meta[DocumentManagement/Folder]],
                [meta[DocumentManagement/File]],
                [meta[DocumentManagement/FileContent]]
            ]
        }]);

        var shell = FolderManagement.renderShell(container);
        var fileList = $("[name=fileList]", shell);

        if (!fileList.length) {
            console.error("FolderManagement fileList container was not rendered.");
            return;
        }

        await FolderManagement.bindBreadcrumbNavigation(shell, app, folder, readOnly, disablePaging);

        var actions = await FolderManagement.loadActionComponents(shell, app);

        FolderManagement.bindToolbarActions(shell, app, folder, readOnly, disablePaging, actions.upload);
        FolderManagement.bindDesktopUploadDrop(shell, app, folder, readOnly, disablePaging, actions.upload);

        await FolderManagement.buildWidget(fileList, folder, readOnly, app, disablePaging);
    },

    renderShell: function (container) {
        var shell = $("[name=folderManagementShell]", container);

        if (!shell.length) {
            shell = $('<div name="folderManagementShell"></div>').appendTo(container);
        }

        shell.html([
            '<div class="folder-management">',
                '<div class="folder-main-toolbar">',
                    '<div class="folder-title-row">',
                        '<div class="folder-breadcrumb" name="folderPath"></div>',
                        '<div class="folder-title-actions">',
                            '<div class="folder-updated" name="folderUpdated"></div>',
                            '<button type="button" class="btn btn-sm btn-primary" name="manageFolder">',
                                '<span class="k-icon k-i-folder-more"></span>',
                                '[resource_displayname[managefolder]]',
                            '</button>',
                        '</div>',
                    '</div>',

                    '<div class="folder-action-row">',
                        '<div class="folder-actions mr-4">',
                            '<button type="button" class="btn btn-sm btn-primary" name="upload"><span class="k-icon k-i-upload"></span> [resource_displayname[upload]]</button>',
                            '<button type="button" class="btn btn-sm btn-primary" name="newFolder"><span class="k-icon k-i-plus"></span> [resource_displayname[newfolder]]</button>',
                        '</div>',

                        '<div class="context-toolbar context-toolbar-hidden" name="contextToolbar">',
                            '<strong name="selectedCount">0 items selected</strong>',
                            '<div class="context-toolbar-actions">',
                                '<button type="button" class="btn btn-sm btn-primary" name="contextMove"><span class="k-icon k-i-arrows-move"></span>[resource_displayname[move]]</button>',
                                '<button type="button" class="btn btn-sm btn-primary" name="contextRename"><span class="k-icon k-i-pencil"></span>[resource_displayname[rename]]</button>',
