    loadActionComponents: async function (shell, app) {
        await FolderManagement.loadDMSFormatting(shell, app);

        return {
            file: await FolderManagement.loadFileActions(shell, app),
            folder: await FolderManagement.loadFolderActions(shell, app),
            upload: await FolderManagement.loadUploadActions(shell, app)
        };
    },

    bindBreadcrumbNavigation: async function (shell, app, folder, readOnly, disablePaging) {
        var breadcrumb = $("[name=folderPath]", shell);

        if (!folder) {
            breadcrumb.empty();
            return;
        }

        var folders = (
            await api.get(
                "DocumentManagement/Folder?$filter=AppId eq " +
                app.Id +
                "&$orderby=Path asc&_=" +
                Date.now()
            )
        ).value || [];

        FolderManagement.renderBreadcrumb(
            breadcrumb,
            folders,
            folder,
            app,
            readOnly,
            disablePaging
        );
    },

    renderBreadcrumb: function (breadcrumb, folders, currentFolder, app, readOnly, disablePaging) {
        breadcrumb.empty();

        if (!currentFolder) {
            return;
        }

        var pathParts = (currentFolder.Path || currentFolder.Name || "")
            .split("/")
            .filter(Boolean);

        if (!pathParts.length) {
            breadcrumb.text(currentFolder.Name || "");
            return;
        }

        var foldersByPath = {};
        var cumulativePath = "";

        for (var i = 0; i < folders.length; i++) {
            foldersByPath[FolderManagement.normalisePath(folders[i].Path)] = folders[i];
        }

        for (var j = 0; j < pathParts.length; j++) {
            cumulativePath = cumulativePath
                ? cumulativePath + "/" + pathParts[j]
                : pathParts[j];

            var matchedFolder = foldersByPath[
                FolderManagement.normalisePath(cumulativePath)
            ];

            if (j > 0) {
                $("<span />")
                    .addClass("folder-breadcrumb-separator")
                    .text("/")
                    .appendTo(breadcrumb);
            }

            FolderManagement.buildBreadcrumbSegment(
                matchedFolder,
                pathParts[j],
                j === pathParts.length - 1,
                app,
                readOnly,
                disablePaging
            ).appendTo(breadcrumb);
        }
    },

    buildBreadcrumbSegment: function (folder, fallbackText, isCurrent, app, readOnly, disablePaging) {
        var segment = $("<a />")
            .attr("href", "#")
            .addClass("folder-breadcrumb-link")
            .toggleClass("folder-breadcrumb-current", isCurrent)
            .text(folder ? folder.Name : fallbackText);

        if (!folder || isCurrent) {
            return segment
                .toggleClass("folder-breadcrumb-missing", !folder)
                .on("click.folderBreadcrumb", function (event) {
                    event.preventDefault();
                });
        }

        segment
            .data("folder", folder)
            .off("click.folderBreadcrumb")
            .on("click.folderBreadcrumb", function (event) {
                event.preventDefault();

                FolderManagement.navigateToBreadcrumbFolder(
                    app,
                    $(this).data("folder"),
                    readOnly,
                    disablePaging
                );
            });

        return segment;
    },

    navigateToBreadcrumbFolder: async function (app, folder, readOnly, disablePaging) {
        await FolderManagement.reloadFolderView(app, folder, readOnly, disablePaging);

        FolderManagement.selectFolderInTree(folder);
    },

    selectFolderInTree: function (folder) {
        var treeElement = $(".component[name=DocumentManagement] [name=treeRoot]");
        var treeView = treeElement.data("kendoTreeView");

        if (!treeView || !folder) {
            return;
        }

        var node = FolderManagement.findTreeNodeByFolderId(treeView.dataSource.view(), folder.Id );

        if (!node) {
            return;
        }

        var treeNode = treeView.findByUid(node.uid);

        if (!treeNode || !treeNode.length) {
            return;
        }

        treeView.select(treeNode);

        if (window.DocumentManagement && DocumentManagement.highlightSelectedPath) {
            DocumentManagement.highlightSelectedPath({ kendoObject: treeView }, treeNode);
        }

        if (window.DocumentManagement && DocumentManagement.updateTreeFolderIcons) {
            DocumentManagement.updateTreeFolderIcons({ kendoObject: treeView });
        }
    },

    findTreeNodeByFolderId: function (nodes, folderId) {
        for (var i = 0; i < nodes.length; i++) {
            if (nodes[i].id === folderId) {
                return nodes[i];
            }

            var childMatch = FolderManagement.findTreeNodeByFolderId(nodes[i].items || [], folderId);

            if (childMatch) {
                return childMatch;
            }
        }

        return null;
    },

    normalisePath: function (path) {
        return (path || "")
            .replace(/^\/+|\/+$/g, "")
            .toLowerCase();
    },

    bindToolbarActions: function (shell, app, folder, readOnly, disablePaging, uploadActions) {
