    loadActions: async function (shell, app, hostName, componentName, callback) {
        var cacheKey = componentName + "Instance";

        if (FolderManagement[cacheKey]) {
            if (callback) {
                await callback(FolderManagement[cacheKey]);
            }

            return FolderManagement[cacheKey];
        }

        var host = $('[name="' + hostName + '"]', shell);
        var loadedComponent = null;

        await loadComponent(host, componentName, async function (component) {
            component = component || window[componentName];

            if (!component || !component.init) {
                console.error(componentName + " failed to load.");
                return;
            }

            await component.init(app, host);
            loadedComponent = component;
            FolderManagement[cacheKey] = component;

            if (callback) {
                await callback(component);
            }
        });

        return loadedComponent;
    },

    buildWidget: async function (element, folder, readOnly, app, disablePaging = false) {
            var selectionKeys = FolderManagement.bindSelectionKeys();

            var datasource = await model.getDatasource({
                endpoint: "DocumentManagement/File",
                odataAppend:
                    "?$filter=FolderId eq " +
                    folder.Id +
                    "&$expand=Contents($select=CreatedOn;$orderBy=CreatedOn desc;$top=1)"
            });

            if (datasource.sort) {
                datasource.sort({ field: "Name", dir: "asc" });
            } else {
                datasource.sort = { field: "Name", dir: "asc" };
            }

            var folderGrid = new GridWidget(
                element,
                datasource
            );

            folderGrid.app = app;
            folderGrid.folder = folder;
            folderGrid.groupable = false;
            folderGrid.editable = false;
            folderGrid.scrollable = true;
            folderGrid.sortable = true;
            folderGrid.filterable = !disablePaging;
            folderGrid.pageable = disablePaging ? false : { pageSizes: false, refresh: true };
            folderGrid.columns = FolderManagement.getColumns();

        folderGrid.dataBound = function () {
            FolderManagement.bindGridSelection(folderGrid, selectionKeys);
            FolderManagement.bindFileDrag(folderGrid);
            FolderManagement.updateContextToolbar(folderGrid);
        };

        folderGrid.detailTemplate = kendo.template("<div name='fileVersionGrid'></div>");

        folderGrid.detailExpand = async function (event) {
            var detailHost = $("[name=fileVersionGrid]", event.detailRow);

            if (!detailHost.length) {
                return;
            }

            if (detailHost.data("loadingVersions")) {
                return;
            }

            detailHost
                .data("loadingVersions", true)
                .empty();

            try {
                await FileActions.expandVersions(event, app, folderGrid, readOnly);
            } finally {
                detailHost.data("loadingVersions", false);
            }
        };

        await folderGrid.init();

        FolderManagement.bindFileSearch(folderGrid);
        FolderManagement.bindContextToolbar(folderGrid);
        FolderManagement.bindGridEvents(folderGrid, readOnly);
        FolderManagement.updateContextToolbar(folderGrid);
        FolderManagement.resizeGrid(folderGrid);
    },

    bindSelectionKeys: function () {
        var keys = {
            shift: false,
            ctrl: false
        };

        $(window)
            .off(".folderManagementSelection")
            .on("keydown.folderManagementSelection", function (event) {
                keys.shift = keys.shift || event.which === 16;
                keys.ctrl = keys.ctrl || event.which === 17;
            })
            .on("keyup.folderManagementSelection", function (event) {
                if (event.which === 16) {
                    keys.shift = false;
                }

                if (event.which === 17) {
                    keys.ctrl = false;
                }
            });

        return keys;
    },

