        }
        var theme = await api.get("DMS/CRM/" + tenant.Id + "/Theme/Colours/colours.json").catch(async () => {
            await api.post("DMS/CRM/" + tenant.Id + "/Theme/Colours/colours.json", {
                "Default": defaultTheme
            });
        })

        var theme = (await api.get("DMS/CRM/" + tenant.Id + "/Theme/Colours/colours.json"));
        $("[name=primaryPicker]", container).kendoColorPicker({ 
            value: theme.colours.primary, 
            buttons: false, 
            views: ["gradient"],
            change: (e) => e.preventDefault() 
            });
        $("[name=secondaryPicker]", container).kendoColorPicker({ 
            value: theme.colours.secondary, 
            buttons: false, 
            views: ["gradient"],
            change: (e) => e.preventDefault() 
            });
        $("[name=chartColour1]", container).kendoColorPicker({ 
            value: theme.colours.charts[2], 
            buttons: false, 
            views: ["gradient"],
            change: (e) => e.preventDefault() 
            });
        $("[name=chartColour2]", container).kendoColorPicker({ 
