        await api.post("DMS/CRM/" + tenant.Id + "/Theme/Content/Slideshow");
        await api.post("DMS/CRM/" + tenant.Id + "/Theme/Colours");
         var slideshow = (await api.get("DocumentManagement/Folder?$filter=AppId eq " + app.Id + " and Path eq 'CRM/"+ tenant.Id + "/Theme/Content/Slideshow'&$expand=Files")).value[0];
        FolderManagement.init(app, $(".component[name=FolderManagement]", $("[name=uploadSlideshowImages]", container)), slideshow, true, true);
        $("[name=save]", container).off("click").on("click", async (e) => await TenantThemeManagement.saveTheme(e, container, theme, tenant));
   },

    saveTheme: async function (e, container, theme, tenant) {
        e.preventDefault();
        theme.colours.primary = $("[name=primaryPicker]", container).val();
        theme.colours.secondary = $("[name=secondaryPicker]", container).val();

        theme.colours.charts[0] = $("[name=primaryPicker]", container).val();
