    "Content": "<script type="text/template" name="universalUploadDialog">
    <div class="upload-files-dialog">
        <div class="upload-files-body">
            <div class="upload-dropzone" name="universalUploadDropzone">
                <div>
                    <div class="upload-dropzone-title">
                        [resource_displayname[dropfilesorfoldershere]]
                    </div>

                    <div class="upload-dropzone-copy">
                        [resource_displayname[uploaditemsintofolder]]
                    </div>
                </div>

                <div class="d-flex gap-2">
                    <input type="file" name="uploadFilesInput" multiple style="display:none;" />
                    <input type="file" name="uploadFolderInput" webkitdirectory directory multiple style="display:none;" />

                    <button type="button" class="btn btn-sm btn-primary" name="chooseFiles">
                        <span class="k-icon k-i-upload"></span>
                        [resource_displayname[choosefiles]]
                    </button>

                    <button type="button" class="btn btn-sm btn-primary" name="chooseFolder">
                        <span class="k-icon k-i-folder"></span>
                        [resource_displayname[choosefolder]]
                    </button>
                </div>
            </div>

            <div class="upload-files-section-title">
                [resource_displayname[selecteditems]]
            </div>

            <div class="upload-files-list" name="selectedUploadItems"></div>
        </div>

        <div class="upload-files-footer">
            <div class="upload-files-footer-note">
                [resource_displayname[uploadingto]]
                <span name="footerFolderPathLabel"></span>
            </div>

            <button type="button" class="btn btn-sm btn-primary" name="uploadSubmit">
                <span class="k-icon k-i-upload"></span>
                [resource_displayname[upload]]
            </button>
        </div>
    </div>
</script>",
    "Script": "UploadActions = {
    init: function (app, container) {
        UploadActions.app = app || session.app;
        UploadActions.container = container || $(".component[name=UploadActions]");
        return UploadActions;
    },

    getTemplate: function (name) {
        return $('[name="' + name + '"]', UploadActions.container).first().html();
    },

    openUniversalUpload: function (folder, onComplete, initialItems) {
        var dialog = new Dialog({
            title: "[resource_displayname[upload]]",
            height: "auto",
            width: 760
        });

        dialog.template = UploadActions.getTemplate("universalUploadDialog");
        dialog.uploadItems = initialItems || [];

        dialog.init(function () {
            UploadActions.bindDialog(dialog, folder, onComplete);
            UploadActions.renderItems(dialog);
        });
    },

    bindDialog: function (dialog, folder, onComplete) {
        $("[name=footerFolderPathLabel]", dialog.element)
            .text(DMSFormatting.folderPath(folder));

        UploadActions.bindChooseButtons(dialog);
        UploadActions.bindInputs(dialog);
        UploadActions.bindDropzone(dialog);
        UploadActions.bindSubmit(dialog, folder, onComplete);
    },

    bindChooseButtons: function (dialog) {
        $("[name=chooseFiles]", dialog.element)
            .off("click.uploadActions")
            .on("click.uploadActions", function (event) {
                event.preventDefault();
                $("[name=uploadFilesInput]", dialog.element).trigger("click");
            });

        $("[name=chooseFolder]", dialog.element)
            .off("click.uploadActions")
            .on("click.uploadActions", function (event) {
                event.preventDefault();
                $("[name=uploadFolderInput]", dialog.element).trigger("click");
            });
    },

    bindInputs: function (dialog) {
        $("[name=uploadFilesInput]", dialog.element)
            .off("change.uploadActions")
            .on("change.uploadActions", function (event) {
                UploadActions.addFiles(dialog, event.target.files);
                $(this).val("");
            });

        $("[name=uploadFolderInput]", dialog.element)
            .off("change.uploadActions")
            .on("change.uploadActions", function (event) {
                UploadActions.addFolder(dialog, event.target.files);
                $(this).val("");
            });
    },

    bindDropzone: function (dialog) {
        $("[name=universalUploadDropzone]", dialog.element)
            .off("dragover.uploadActions dragleave.uploadActions drop.uploadActions")
            .on("dragover.uploadActions", function (event) {
                event.preventDefault();
                event.stopPropagation();
                $(this).addClass("dragover");
            })
            .on("dragleave.uploadActions", function (event) {
                event.preventDefault();
                event.stopPropagation();
                $(this).removeClass("dragover");
            })
            .on("drop.uploadActions", async function (event) {
                event.preventDefault();
                event.stopPropagation();

                $(this).removeClass("dragover");

                UploadActions.addItems(
                    dialog,
                    await UploadActions.getDroppedUploadItems(event.originalEvent)
                );
            });
    },

    bindSubmit: function (dialog, folder, onComplete) {
        $("[name=uploadSubmit]", dialog.element)
            .off("click.uploadActions")
            .on("click.uploadActions", async function (event) {
                event.preventDefault();
                await UploadActions.uploadItems(dialog, folder, onComplete);
            });
    },

    addFiles: function (dialog, files) {
        UploadActions.addItems(
            dialog,
            UploadActions.getDroppedFileUploadItems(files)
        );
    },

    addFolder: function (dialog, files) {
        if (!files || !files.length) {
            return;
        }

        UploadActions.addItems(dialog, [
            UploadActions.folderItem(Array.from(files))
        ]);
    },

    addItems: function (dialog, items) {
        if (!items || !items.length) {
            return;
        }

        for (var i = 0; i < items.length; i++) {
            dialog.uploadItems.push(items[i]);
        }

        UploadActions.renderItems(dialog);
    },

    renderItems: function (dialog) {
        var list = $("[name=selectedUploadItems]", dialog.element);
        var button = $("[name=uploadSubmit]", dialog.element);

        list.empty();

        if (!dialog.uploadItems.length) {
            list.html('<div class="upload-file-subtext">[resource_displayname[nothingselected]]</div>');
            button.prop("disabled", true);
            return;
        }

        for (var i = 0; i < dialog.uploadItems.length; i++) {
            list.append(UploadActions.buildRow(dialog.uploadItems[i], i));
        }

        $(".upload-file-remove", list)
            .off("click.uploadActions")
            .on("click.uploadActions", function (event) {
                event.preventDefault();
                event.stopPropagation();

                dialog.uploadItems.splice(parseInt($(this).attr("data-index"), 10), 1);
                UploadActions.renderItems(dialog);
            });

        button.prop("disabled", false);
    },

    buildRow: function (item, index) {
        var iconName = item.type === "folder"
            ? "folder"
            : DMSFormatting.extension(item.name);

        var subtext =
            DMSFormatting.fileSize(item.size) +
            " Modified " +
            DMSFormatting.fileDate(item.lastModified);

        if (item.type === "folder") {
            subtext +=
                " Contains " +
                item.files.length +
                " File" +
                (item.files.length === 1 ? "" : "s");
        }

        var row = $([
            '<div class="upload-file-row">',
                '<div class="upload-file-icon">',
                    '<img src="/icons/',
                        iconName,
                        '.svg" alt="" onerror="this.src=\'/icons/default.svg\';" />',
                "</div>",
                '<div class="upload-file-meta">',
                    '<div class="upload-file-name"></div>',
                    '<div class="upload-file-subtext"></div>',
                "</div>",
                '<button type="button" class="upload-file-remove" data-index="' + index + '">&times;</button>',
            "</div>"
        ].join(""));

        $(".upload-file-name", row).text(item.name);
        $(".upload-file-subtext", row).text(subtext);

        return row;
    },

    uploadItems: async function (dialog, folder, onComplete) {
        if (!dialog.uploadItems.length) {
            error("[resource_displayname[nothingselected]]");
            return;
        }

        var button = $("[name=uploadSubmit]", dialog.element);

        button.prop("disabled", true).text("[resource_displayname[uploading]]");

        try {
            for (var i = 0; i < dialog.uploadItems.length; i++) {
                await UploadActions.uploadItem(folder, dialog.uploadItems[i]);
            }

            dialog.events.close();

            if (onComplete) {
                await onComplete(UploadActions.getCreatedUploadFolder(folder, dialog.uploadItems));
            }
        } catch (err) {
            button
                .prop("disabled", false)
                .html('<span class="k-icon k-i-upload"></span>[resource_displayname[upload]]');

            error(err);
        }
    },

    uploadItem: async function (folder, item) {
        if (item.type === "folder") {
            await UploadActions.uploadFolder(folder, item);
            return;
        }

        await UploadActions.uploadFile(folder, item.file);
    },

    uploadFile: function (folder, file) {
        return new Promise(function (resolve) {
            api.file.upload(
                folder.Path + "/" + (file.relativePath || file.webkitRelativePath || file.name),
                file,
                resolve
            );
        });
    },

    uploadFolder: async function (folder, item) {
        for (var i = 0; i < item.files.length; i++) {
            await UploadActions.uploadFile(folder, item.files[i]);
        }
    },

    getDroppedUploadItems: async function (event) {
        var dataTransfer = event.dataTransfer;

        if (!dataTransfer) {
            return [];
        }

        if (
            dataTransfer.items &&
            dataTransfer.items.length &&
            UploadActions.dropContainsDirectory(dataTransfer.items)
        ) {
            return await UploadActions.getDroppedItemUploadItems(dataTransfer.items);
        }

        return UploadActions.getDroppedFileUploadItems(dataTransfer.files);
    },

    getDroppedFileUploadItems: function (files) {
        var uploadItems = [];

        if (!files || !files.length) {
            return uploadItems;
        }

        for (var i = 0; i < files.length; i++) {
            uploadItems.push(UploadActions.fileItem(files[i]));
        }

        return uploadItems;
    },

    getDroppedItemUploadItems: async function (items) {
        var uploadItems = [];

        for (var i = 0; i < items.length; i++) {
            var entry = items[i].webkitGetAsEntry
                ? items[i].webkitGetAsEntry()
                : null;

            if (!entry) {
                var file = items[i].getAsFile();

                if (file) {
                    uploadItems.push(UploadActions.fileItem(file));
                }

                continue;
            }

            if (entry.isFile) {
                uploadItems.push(
                    UploadActions.fileItem(
                        await UploadActions.readDroppedFile(entry, "")
                    )
                );
            }

            if (entry.isDirectory) {
                uploadItems.push(
                    UploadActions.folderItem(
                        await UploadActions.readDroppedDirectory(entry, entry.name),
                        entry.name
                    )
                );
            }
        }

        return uploadItems;
    },

    dropContainsDirectory: function (items) {
        for (var i = 0; i < items.length; i++) {
            var entry = items[i].webkitGetAsEntry
                ? items[i].webkitGetAsEntry()
                : null;

            if (entry && entry.isDirectory) {
                return true;
            }
        }

        return false;
    },

    readDroppedDirectory: async function (directoryEntry, path) {
        var files = [];
        var entries = await UploadActions.readDirectoryEntries(directoryEntry);

        for (var i = 0; i < entries.length; i++) {
            var entry = entries[i];

            if (entry.isFile) {
                files.push(await UploadActions.readDroppedFile(entry, path));
            }

            if (entry.isDirectory) {
                files = files.concat(
                    await UploadActions.readDroppedDirectory(
                        entry,
                        path + "/" + entry.name
                    )
                );
            }
        }

        return files;
    },

    readDirectoryEntries: function (directoryEntry) {
        return new Promise(function (resolve) {
            var reader = directoryEntry.createReader();
            var entries = [];

            var readEntries = function () {
                reader.readEntries(function (results) {
                    if (!results.length) {
                        resolve(entries);
                        return;
                    }

                    entries = entries.concat(Array.prototype.slice.call(results));
                    readEntries();
                });
            };

            readEntries();
        });
    },

    readDroppedFile: function (fileEntry, path) {
        return new Promise(function (resolve) {
            fileEntry.file(function (file) {
                if (path) {
                    file.relativePath = path + "/" + file.name;
                }

                resolve(file);
            });
        });
    },

    fileItem: function (file) {
        return {
            type: "file",
            name: file.name,
            file: file,
            size: file.size,
            lastModified: file.lastModified
        };
    },

    folderItem: function (files, folderName) {
        files = files || [];

        var firstFile = files.length ? files[0] : null;
        var relativePath = firstFile
            ? firstFile.webkitRelativePath || firstFile.relativePath || ""
            : "";

        return {
            type: "folder",
            name: folderName || (relativePath ? relativePath.split("/")[0] : "Selected Folder"),
            files: files,
            size: UploadActions.totalSize(files),
            lastModified: firstFile ? firstFile.lastModified : null
        };
    },

    totalSize: function (files) {
        return (files || []).reduce(function (total, file) {
            return total + (file.size || 0);
        }, 0);
    },

    getCreatedUploadFolder: function (parentFolder, uploadItems) {
        var folderItem = (uploadItems || []).filter(function (item) {
            return item.type === "folder" || item.isFolder;
        })[0];

        if (!folderItem) {
            return null;
        }

        var folderName = folderItem.name || folderItem.Name;

        if (!folderName) {
            return null;
        }

        return {
            AppId: parentFolder.AppId,
            Name: folderName,
            ParentId: parentFolder.Id,
            Path: parentFolder.Path.replace(/\/+$/g, "") + "/" + folderName.toLowerCase()
        };
    },
};",
